#include "cartmesh2d/fv/SstRans2D.hpp"
#include "cartmesh2d/io/MeshIO2D.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <chrono>
#include <cmath>
#include <algorithm>
using namespace cartmesh2d;using namespace cartmesh2d::fv;
int main(int argc,char** argv){try{
 auto topology=readCm2dTopology(argv[1]);if(!topology.valid())throw std::runtime_error(topology.error);
 auto mesh=makeFvMesh2D(topology.topology);std::ifstream in(argv[2]);std::size_t n,nf;FrozenSst2003mProblem2D p;
 in>>n>>nf>>p.nu;if(n!=mesh.cells.size()||nf!=mesh.faces.size())throw std::runtime_error("size");
 p.k.resize(n);p.omega.resize(n);p.wallDistance.resize(n);std::vector<Vector2D> velocity(n);
 for(std::size_t i=0;i<n;++i)in>>p.k[i]>>p.omega[i]>>p.wallDistance[i]>>velocity[i].x>>velocity[i].y;
 p.volumeFlux.resize(nf);p.resolvedWalls.resize(nf);p.boundaryK.resize(nf);p.boundaryOmega.resize(nf);std::vector<SstVelocityBoundary2D> bc(nf);
 for(std::size_t i=0;i<nf;++i){bool wall,value;in>>p.volumeFlux[i]>>wall>>value>>p.boundaryK[i].value>>p.boundaryOmega[i].value>>bc[i].value.x>>bc[i].value.y>>bc[i].fixedX>>bc[i].fixedY;
 p.resolvedWalls[i]=wall;p.boundaryK[i].kind=p.boundaryOmega[i].kind=value?ScalarBoundaryKind2D::Value:ScalarBoundaryKind2D::DiffusiveFlux;}
 if(!in)throw std::runtime_error("state parse");
 SstTransportControls2D c;c.maxIterations=std::stoul(argv[4]);c.scalarCorrectionsPerUpdate=1;c.relaxation=std::stod(argv[5]);c.transport.preconditioner=ScalarPreconditioner2D::ILU0;
 auto start=std::chrono::steady_clock::now();const auto count=c.maxIterations;c.maxIterations=1;
 std::vector<double> scale(2*n),lastF,lastG;
 for(std::size_t i=0;i<n;++i){scale[i]=std::max(p.k[i],2.25e-7);scale[n+i]=std::max(p.omega[i],125.);}
 std::ofstream out(std::string(argv[3])+".csv");out<<std::setprecision(17)<<"iteration,kNorm,omegaNorm,kCell,omegaCell,accepted,alpha\n";
 SstTransportResult2D r;int accepted=0,rejected=0;
 const auto merit=[](const auto& h){return std::max(h.kCellResidual,h.omegaCellResidual)/1e-9;};
 for(std::size_t it=0;it<count;++it){
  r=solveSst2003mTransport2D(mesh,p,velocity,bc,c);
  std::vector<double> f(2*n),g(2*n);
  for(std::size_t i=0;i<n;++i){g[i]=r.fields.k.values[i];g[n+i]=r.fields.omega.values[i];f[i]=(g[i]-p.k[i])/scale[i];f[n+i]=(g[n+i]-p.omega[i])/scale[n+i];}
  bool used=false;double alpha=0;
  if(!lastF.empty()&&!r.converged){double num=0,den=0;for(std::size_t i=0;i<2*n;++i){double d=f[i]-lastF[i];num+=f[i]*d;den+=d*d;}
   if(den>0){alpha=num/den;auto trial=p;bool valid=std::isfinite(alpha);
    for(std::size_t i=0;i<n;++i){trial.k[i]=g[i]-alpha*(g[i]-lastG[i]);trial.omega[i]=g[n+i]-alpha*(g[n+i]-lastG[n+i]);valid=valid&&std::isfinite(trial.k[i])&&trial.k[i]>=0&&std::isfinite(trial.omega[i])&&trial.omega[i]>0;}
    if(valid){auto check=solveSst2003mTransport2D(mesh,trial,velocity,bc,c);
     if(merit(check.history.front())<merit(r.history.back())) {p=std::move(trial);used=true;++accepted;}}
   }
   if(!used)++rejected;
  }
  lastF=std::move(f);lastG=std::move(g);
  if(!used){p.k=r.fields.k.values;p.omega=r.fields.omega.values;}
  auto h=r.history.front();out<<it<<','<<h.kResidualNorm<<','<<h.omegaResidualNorm<<','<<h.kCellResidual<<','<<h.omegaCellResidual<<','<<used<<','<<alpha<<'\n';
  if(r.converged)break;
 }
 std::cout<<std::setprecision(17)<<"converged="<<r.converged<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<" accepted="<<accepted<<" rejected="<<rejected<<'\n';

 return r.converged?0:2;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
